```pseudocode
func RenderBlackbody(frame, dist, eyepos, center, radius, sigma, alpha, beta, wavelength)
  // Helpers
  func DistanceToSample(sample, origin, direction)
    // calculate distance from origin to sample along direction
    return dot(sample - origin, direction) / length(direction)

  func RefractWave(travelDistance)
    // calculate refraction angle
    refractAngle = arccos((n2 - n1) * cos(incidentAngle) + n1 * sin(incidentAngle))
    return refractAngle

  func Phi(incidentAngle, exitAngle, a)
    // calculate exit angle
    exitAngle = arccos((a + cos(incidentAngle)) / (1 + a * cos(incidentAngle)))
    return exitAngle

  // Main algorithm
  // Initialize
  rays = []
  sampleDistances = []
  illuminance = 0
  maxDistance = distance from center to eyepos

  // Iterate over samples
  for sample in frame
    // Calculate sample distance from eyepos
    sampleDistance = distanceToSample(sample, eyepos, (sample - center) / radius)

    // If sample is within view range
    if sampleDistance < maxDistance
      // Initialize ray data
      ray = [sample, sampleDistance, 0, 0] // [sample, distance, incidentAngle, refractedAngle]

      // Calculate incident angle
      incidentAngle = arccos(dot((sample - center), (eyepos - center)) / (length(sample - center) * length(eyepos - center)))

      // Refract ray
      refractedAngle = refractWave(incidentAngle)
      ray[incidentAngle] = incidentAngle
      ray[refractedAngle] = refractedAngle

      // Add ray to list
      rays.append(ray)
      sampleDistances.append(sampleDistance)

  // Iterate over rays
  for ray in rays
    // Calculate exit angle
    exitAngle = phi(ray[incidentAngle], ray[refractedAngle], alpha)
    exitsAngle = phi(exitAngle, 0, beta) // manual calculation of exit angle

    // Update illuminance
    illuminance += exponential(-distanceToSample(ray[0], eyepos, (ray[0] - center) / radius) / wavelength) * cos(ray[incidentAngle]) * cos(exitsAngle)

  return illuminance
```

